def _format_seconds(seconds: float) -> str:
    """Format a non-negative number of seconds without a needless fraction."""
    seconds = float(seconds)
    if seconds.is_integer():
        return str(int(seconds))

    text = repr(seconds)
    # Shorten only when a shorter decimal is within a float ULP of the same
    # value, so artifacts such as 0.1 + 0.2 -> 0.30000000000000004 read as 0.3
    # while meaningful extra digits are kept.
    for precision in range(1, 18):
        candidate = f"{seconds:.{precision}g}"
        if math.isclose(float(candidate), seconds, rel_tol=1e-15):
            text = candidate
            break

    if "e" in text or "E" in text:
        text = f"{Decimal(text):f}"
    return text

